const extraTranslations = {"ru":{"navWhy":"Зачем водопад?","navClient":"Клиентам","whyKicker":"БОЛЬШЕ, ЧЕМ РОСКОШЬ","whyTitle":"Больше, чем роскошь. Инвестиция в качество жизни.","whyIntro":"Водопад объединяет природу, архитектуру и инженерные решения. Он может стать центром частной резиденции или узнаваемой особенностью коммерческого пространства.","benefit1Label":"01 / БЛАГОПОЛУЧИЕ","benefit1Title":"Здоровье и благополучие","benefit1Text":"Звук текущей воды может помогать снижать стресс и поддерживать расслабление. Движение воды создаёт спокойную атмосферу для отдыха и медитации. В помещении циркуляция воды при грамотном проектировании и обслуживании может помогать поддерживать комфортную влажность.","benefit2Label":"02 / ЦЕННОСТЬ НЕДВИЖИМОСТИ","benefit2Title":"Индивидуальность недвижимости","benefit2Text":"Уникальный архитектурный акцент усиливает визуальную привлекательность участка и создаёт эксклюзивную среду. Он помогает недвижимости запомниться и может повысить её привлекательность для потенциальных покупателей.","benefit3Label":"03 / ЭКСКЛЮЗИВНОСТЬ","benefit3Title":"Престиж и эксклюзивность","benefit3Text":"Индивидуальный водопад отражает вкус владельца и становится выразительным центром частной резиденции, роскошного отеля, SPA, ресторана или коммерческого объекта.","benefit4Label":"04 / БИЗНЕС-ЦЕННОСТЬ","benefit4Title":"Коммерческая ценность","benefit4Text":"Для отелей, курортов, SPA и ресторанов водопад может стать точкой притяжения. Он создаёт запоминающийся опыт, стимулирует фотографии и публикации в соцсетях, укрепляет бренд и может поддерживать удовлетворённость гостей и повторные визиты.","benefit5Label":"05 / ПРИРОДА И АРХИТЕКТУРА","benefit5Title":"Природа и архитектура","benefit5Text":"Вода, натуральный камень и движение создают живую архитектурную композицию. Каждый объект уникален: форму, масштаб, звук и внешний вид адаптируют к окружению, назначению и видению клиента.","benefit6Label":"06 / ДОЛГОСРОЧНАЯ ЦЕННОСТЬ","benefit6Title":"Долгосрочная ценность","benefit6Text":"Профессионально спроектированный водопад — инвестиция не только во внешний вид, но и в качество пространства, впечатления и индивидуальность. При правильном обслуживании он может оставаться ценным элементом долгие годы.","whySignoff":"БОЛЬШЕ, ЧЕМ ВОДНЫЙ ОБЪЕКТ. ЖИВОЕ ВПЕЧАТЛЕНИЕ.","clientKicker":"ЛИЧНЫЙ КАБИНЕТ КЛИЕНТА AQUAFORMA","clientTitle":"Выберите, с чего хотите начать","clientIntro":"Здесь можно отправить проект на оценку, посмотреть обучающие программы, выбрать товары или задать вопрос по вашей задаче. Все отправленные данные сохраняются в системе AquaForma.","client1Title":"Заявка на водопад","client1Text":"Пять основных вопросов о проекте, контакты и фотографии объекта.","client1Link":"Заполнить заявку ↗","client2Title":"Flowerbeds & Alpine Gardens","client2Text":"Групповое и индивидуальное обучение с выбором формата.","client2Link":"Посмотреть курсы ↗","client3Title":"Магазин","client3Text":"Каталог товаров, онлайн-оплата небольших сумм и запрос счёта для крупных заказов.","client3Link":"Перейти к товарам ↗","client4Title":"Консультация","client4Text":"Задайте вопрос и прикрепите фотографию, видео или документ.","client4Link":"Задать вопрос ↗","client5Title":"Портфолио","client5Text":"Галерея водных решений и визуальных примеров AquaForma.","client5Link":"Открыть портфолио ↗"},"en":{"navWhy":"Why a waterfall?","navClient":"For clients","whyKicker":"MORE THAN LUXURY","whyTitle":"More than luxury. An investment in life.","whyIntro":"A waterfall brings nature, architecture and engineering together. It can become the centrepiece of a private residence or a distinctive feature of a commercial space.","benefit1Label":"01 / WELL-BEING","benefit1Title":"Health & well-being","benefit1Text":"The sound of flowing water can help reduce stress and encourage relaxation. Moving water creates a calming setting for rest and meditation. Indoors, a properly designed and maintained circulation system can also help maintain comfortable humidity levels.","benefit2Label":"02 / PROPERTY VALUE","benefit2Title":"A distinctive property","benefit2Text":"A distinctive architectural feature enhances the visual appeal of a property and creates an exclusive environment. It makes a property more memorable and can increase its attractiveness to potential buyers.","benefit3Label":"03 / EXCLUSIVITY","benefit3Title":"Prestige & exclusivity","benefit3Text":"A bespoke waterfall is a statement of individuality and refined taste. It can become the architectural centrepiece of a private residence, luxury hotel, SPA, restaurant or exclusive commercial property.","benefit4Label":"04 / BUSINESS VALUE","benefit4Title":"Commercial value","benefit4Text":"For hotels, resorts, SPA centres and restaurants, a waterfall can become a strong visitor attraction. It creates memorable experiences, encourages photography and social sharing, strengthens brand identity and can support customer satisfaction and repeat visits.","benefit5Label":"05 / NATURE & ARCHITECTURE","benefit5Title":"Nature & architecture","benefit5Text":"Water, natural stone and movement create a living architectural experience. Every waterfall is unique: its design, scale, sound and appearance can be adapted to the surrounding environment and the client's vision.","benefit6Label":"06 / LONG-TERM VALUE","benefit6Title":"Long-term value","benefit6Text":"A professionally designed waterfall is an investment in more than appearance: it adds quality, experience and individuality to a space. With appropriate maintenance, it can provide lasting value for many years.","whySignoff":"MORE THAN A WATER FEATURE. A LIVING EXPERIENCE.","clientKicker":"AQUAFORMA CLIENT AREA","clientTitle":"Choose where you would like to start","clientIntro":"Submit a project for review, explore learning programmes, browse products or ask a question. Your submitted information is saved in the AquaForma system.","client1Title":"Waterfall application","client1Text":"Five key project questions, your contact details and site photos.","client1Link":"Submit an application ↗","client2Title":"Flowerbeds & Alpine Gardens","client2Text":"Choose between group learning and individual tuition.","client2Link":"Explore courses ↗","client3Title":"Shop","client3Text":"Browse products, pay small amounts online or request an invoice for larger orders.","client3Link":"Browse products ↗","client4Title":"Consultation","client4Text":"Ask a question and attach a photo, video or document.","client4Link":"Ask a question ↗","client5Title":"Portfolio","client5Text":"A gallery of water-feature concepts and AquaForma visual references.","client5Link":"View portfolio ↗"},"pl":{"navWhy":"Dlaczego wodospad?","navClient":"Dla klientów","whyKicker":"WIĘCEJ NIŻ LUKSUS","whyTitle":"Więcej niż luksus. Inwestycja w jakość życia.","whyIntro":"Wodospad łączy naturę, architekturę i inżynierię. Może stać się centralnym elementem prywatnej rezydencji lub wyróżnikiem przestrzeni komercyjnej.","benefit1Label":"01 / DOBROSTAN","benefit1Title":"Zdrowie i dobre samopoczucie","benefit1Text":"Dźwięk płynącej wody może pomagać ograniczać stres i sprzyjać relaksowi. Ruch wody tworzy spokojną atmosferę odpoczynku i medytacji. W pomieszczeniach prawidłowo zaprojektowany i utrzymywany obieg może pomagać zachować komfortowy poziom wilgotności.","benefit2Label":"02 / WARTOŚĆ NIERUCHOMOŚCI","benefit2Title":"Wyjątkowy charakter nieruchomości","benefit2Text":"Wyjątkowy detal architektoniczny wzmacnia atrakcyjność wizualną posesji i tworzy ekskluzywne otoczenie. Sprawia, że nieruchomość jest bardziej zapamiętywana i może zwiększyć jej atrakcyjność dla potencjalnych nabywców.","benefit3Label":"03 / EKSKLUZYWNOŚĆ","benefit3Title":"Prestiż i wyjątkowość","benefit3Text":"Indywidualny wodospad podkreśla gust i osobowość właściciela. Może stać się architektonicznym centrum prywatnej rezydencji, luksusowego hotelu, SPA, restauracji lub obiektu komercyjnego.","benefit4Label":"04 / WARTOŚĆ BIZNESOWA","benefit4Title":"Wartość komercyjna","benefit4Text":"W hotelach, kurortach, SPA i restauracjach wodospad może być atrakcją przyciągającą gości. Tworzy niezapomniane wrażenia, zachęca do fotografowania i udostępniania w mediach społecznościowych, wzmacnia markę oraz może wspierać zadowolenie i powroty klientów.","benefit5Label":"05 / NATURA I ARCHITEKTURA","benefit5Title":"Natura i architektura","benefit5Text":"Woda, naturalny kamień i ruch tworzą żywe doświadczenie architektoniczne. Każdy wodospad jest wyjątkowy: projekt, skala, dźwięk i wygląd można dopasować do otoczenia oraz wizji klienta.","benefit6Label":"06 / WARTOŚĆ NA LATA","benefit6Title":"Długoterminowa wartość","benefit6Text":"Profesjonalnie zaprojektowany wodospad to inwestycja nie tylko w wygląd, ale także w jakość przestrzeni, doświadczenie i indywidualność. Przy odpowiedniej pielęgnacji może zachować wartość przez wiele lat.","whySignoff":"WIĘCEJ NIŻ ELEMENT WODNY. ŻYWE DOŚWIADCZENIE.","clientKicker":"STREFA KLIENTA AQUAFORMA","clientTitle":"Wybierz, od czego chcesz zacząć","clientIntro":"Prześlij projekt do oceny, poznaj programy szkoleniowe, przeglądaj produkty lub zadaj pytanie. Dane są zapisywane w systemie AquaForma.","client1Title":"Zgłoszenie wodospadu","client1Text":"Pięć kluczowych pytań o projekt, dane kontaktowe i zdjęcia lokalizacji.","client1Link":"Wyślij zgłoszenie ↗","client2Title":"Flowerbeds & Alpine Gardens","client2Text":"Wybierz szkolenie grupowe lub indywidualne.","client2Link":"Zobacz kursy ↗","client3Title":"Sklep","client3Text":"Produkty, płatności online za mniejsze kwoty i faktury za większe zamówienia.","client3Link":"Przejdź do produktów ↗","client4Title":"Konsultacja","client4Text":"Zadaj pytanie i dołącz zdjęcie, wideo lub dokument.","client4Link":"Zadaj pytanie ↗","client5Title":"Portfolio","client5Text":"Galeria rozwiązań wodnych i materiałów wizualnych AquaForma.","client5Link":"Otwórz portfolio ↗"},"de":{"navWhy":"Warum ein Wasserfall?","navClient":"Für Kunden","whyKicker":"MEHR ALS LUXUS","whyTitle":"Mehr als Luxus. Eine Investition in Lebensqualität.","whyIntro":"Ein Wasserfall verbindet Natur, Architektur und Ingenieurkunst. Er kann zum Mittelpunkt einer privaten Residenz oder zum markanten Merkmal einer gewerblichen Fläche werden.","benefit1Label":"01 / WOHLBEFINDEN","benefit1Title":"Gesundheit und Wohlbefinden","benefit1Text":"Das Geräusch fließenden Wassers kann Stress reduzieren und Entspannung fördern. Bewegtes Wasser schafft eine beruhigende Atmosphäre für Erholung und Meditation. In Innenräumen kann ein fachgerecht geplantes und gewartetes Wassersystem zu einer angenehmen Luftfeuchtigkeit beitragen.","benefit2Label":"02 / IMMOBILIENWERT","benefit2Title":"Ein unverwechselbares Objekt","benefit2Text":"Ein einzigartiges architektonisches Detail steigert die visuelle Attraktivität eines Grundstücks und schafft ein exklusives Ambiente. Es macht eine Immobilie einprägsamer und kann ihre Attraktivität für potenzielle Käufer erhöhen.","benefit3Label":"03 / EXKLUSIVITÄT","benefit3Title":"Prestige und Exklusivität","benefit3Text":"Ein individuell gestalteter Wasserfall ist Ausdruck von Persönlichkeit und anspruchsvollem Geschmack. Er kann zum architektonischen Mittelpunkt einer privaten Residenz, eines Luxushotels, SPA, Restaurants oder Gewerbeobjekts werden.","benefit4Label":"04 / GESCHÄFTSWERT","benefit4Title":"Kommerzieller Mehrwert","benefit4Text":"In Hotels, Resorts, SPA-Zentren und Restaurants kann ein Wasserfall Besucher anziehen. Er schafft unvergessliche Erlebnisse, regt zum Fotografieren und Teilen in sozialen Medien an, stärkt die Marke und kann die Gästezufriedenheit sowie Wiederbesuche fördern.","benefit5Label":"05 / NATUR & ARCHITEKTUR","benefit5Title":"Natur und Architektur","benefit5Text":"Wasser, Naturstein und Bewegung schaffen ein lebendiges architektonisches Erlebnis. Jeder Wasserfall ist einzigartig: Design, Größe, Klang und Erscheinung werden an die Umgebung und die Vorstellungen des Kunden angepasst.","benefit6Label":"06 / LANGFRISTIGER WERT","benefit6Title":"Langfristiger Wert","benefit6Text":"Ein professionell geplanter Wasserfall ist eine Investition nicht nur in die Optik, sondern auch in Raumqualität, Erlebnis und Individualität. Bei richtiger Pflege kann er viele Jahre lang einen bleibenden Wert bieten.","whySignoff":"MEHR ALS EIN WASSERELEMENT. EIN LEBENDIGES ERLEBNIS.","clientKicker":"AQUAFORMA KUNDENBEREICH","clientTitle":"Wählen Sie, womit Sie beginnen möchten","clientIntro":"Reichen Sie ein Projekt zur Prüfung ein, entdecken Sie Kurse, stöbern Sie in Produkten oder stellen Sie eine Frage. Ihre Angaben werden im AquaForma-System gespeichert.","client1Title":"Wasserfall-Anfrage","client1Text":"Fünf wichtige Projektfragen, Kontaktdaten und Fotos des Standorts.","client1Link":"Anfrage senden ↗","client2Title":"Flowerbeds & Alpine Gardens","client2Text":"Wählen Sie zwischen Gruppen- und Einzelunterricht.","client2Link":"Kurse ansehen ↗","client3Title":"Shop","client3Text":"Produkte, Online-Zahlung kleiner Beträge und Rechnungsanfragen für größere Bestellungen.","client3Link":"Produkte ansehen ↗","client4Title":"Beratung","client4Text":"Stellen Sie eine Frage und fügen Sie ein Foto, Video oder Dokument bei.","client4Link":"Frage stellen ↗","client5Title":"Portfolio","client5Text":"Eine Galerie mit Wasserlösungen und visuellen AquaForma-Referenzen.","client5Link":"Portfolio öffnen ↗"},"fr":{"navWhy":"Pourquoi une cascade ?","navClient":"Espace client","whyKicker":"PLUS QU’UN LUXE","whyTitle":"Plus qu’un luxe. Un investissement dans la qualité de vie.","whyIntro":"Une cascade réunit la nature, l’architecture et l’ingénierie. Elle peut devenir la pièce maîtresse d’une résidence privée ou un élément distinctif d’un espace commercial.","benefit1Label":"01 / BIEN-ÊTRE","benefit1Title":"Santé et bien-être","benefit1Text":"Le bruit de l’eau qui coule peut aider à réduire le stress et favoriser la détente. Le mouvement de l’eau crée une atmosphère apaisante pour le repos et la méditation. À l’intérieur, un circuit bien conçu et entretenu peut contribuer à maintenir un taux d’humidité confortable.","benefit2Label":"02 / VALEUR IMMOBILIÈRE","benefit2Title":"Un bien distinctif","benefit2Text":"Un détail architectural unique renforce l’attrait visuel d’une propriété et crée un environnement exclusif. Il rend le bien plus mémorable et peut accroître son attractivité auprès d’acheteurs potentiels.","benefit3Label":"03 / EXCLUSIVITÉ","benefit3Title":"Prestige et exclusivité","benefit3Text":"Une cascade conçue sur mesure exprime l’individualité et le goût du propriétaire. Elle peut devenir le point central architectural d’une résidence privée, d’un hôtel de luxe, d’un SPA, d’un restaurant ou d’un espace commercial exclusif.","benefit4Label":"04 / VALEUR COMMERCIALE","benefit4Title":"Valeur pour l’activité","benefit4Text":"Dans les hôtels, resorts, centres SPA et restaurants, une cascade peut devenir une attraction. Elle crée des expériences mémorables, encourage les photos et les partages sur les réseaux sociaux, renforce la marque et peut favoriser la satisfaction et le retour des clients.","benefit5Label":"05 / NATURE & ARCHITECTURE","benefit5Title":"Nature et architecture","benefit5Text":"L’eau, la pierre naturelle et le mouvement créent une expérience architecturale vivante. Chaque cascade est unique : son design, son échelle, son son et son apparence s’adaptent à l’environnement et à la vision du client.","benefit6Label":"06 / VALEUR DURABLE","benefit6Title":"Une valeur à long terme","benefit6Text":"Une cascade conçue par des professionnels est un investissement qui va au-delà de l’apparence : elle apporte qualité, expérience et singularité à un espace. Avec un entretien adapté, elle peut conserver sa valeur pendant de nombreuses années.","whySignoff":"PLUS QU’UN ÉLÉMENT AQUATIQUE. UNE EXPÉRIENCE VIVANTE.","clientKicker":"ESPACE CLIENT AQUAFORMA","clientTitle":"Choisissez par où commencer","clientIntro":"Soumettez un projet pour examen, découvrez les formations, parcourez les produits ou posez une question. Vos informations sont enregistrées dans le système AquaForma.","client1Title":"Demande de cascade","client1Text":"Cinq questions essentielles sur le projet, vos coordonnées et des photos du site.","client1Link":"Envoyer une demande ↗","client2Title":"Flowerbeds & Alpine Gardens","client2Text":"Choisissez une formation en groupe ou un accompagnement individuel.","client2Link":"Voir les formations ↗","client3Title":"Boutique","client3Text":"Produits, paiement en ligne des petits montants et demande de facture pour les commandes importantes.","client3Link":"Voir les produits ↗","client4Title":"Consultation","client4Text":"Posez une question et joignez une photo, une vidéo ou un document.","client4Link":"Poser une question ↗","client5Title":"Portfolio","client5Text":"Galerie de solutions aquatiques et de références visuelles AquaForma.","client5Link":"Voir le portfolio ↗"}};
Object.keys(extraTranslations).forEach(lang => Object.assign(dict[lang], extraTranslations[lang]));
const API_BASE_URL = "__API_BASE_URL__";

function setLang(lang){
  const d = dict[lang] || dict.ru;
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-i18n]").forEach(el=>{
    const k = el.dataset.i18n;
    if(d[k]) el.textContent = d[k];
  });
  document.getElementById("language").value = lang;
  document.title = "AquaForma — " + ({
    ru:"архитектура воды",
    pl:"architektura wody",
    en:"water architecture",
    de:"Wasserarchitektur",
    fr:"architecture aquatique"
  }[lang] || "water architecture");
}

document.getElementById("language").addEventListener("change", e => setLang(e.target.value));

const menuButton = document.querySelector(".mobile-menu"),
      navLinks = document.querySelector(".navlinks");
menuButton.addEventListener("click", () => {
  const open = navLinks.classList.toggle("mobile-open");
  menuButton.setAttribute("aria-expanded", String(open));
});
navLinks.querySelectorAll("a").forEach(a => a.addEventListener("click", () => {
  navLinks.classList.remove("mobile-open");
  menuButton.setAttribute("aria-expanded", "false");
}));

document.getElementById("year").textContent = new Date().getFullYear();

document.getElementById("contactForm").addEventListener("submit", async e => {
  e.preventDefault();
  const form = e.currentTarget,
        button = form.querySelector('button[type="submit"]'),
        notice = document.getElementById("formNotice"),
        f = new FormData(form),
        lang = document.getElementById("language").value;

  const m = {
    ru:["Отправляем заявку…","Спасибо! Заявка отправлена.","Не удалось отправить заявку. Попробуйте позже."],
    pl:["Wysyłanie…","Dziękujemy! Zapytanie zostało wysłane.","Nie udało się wysłać. Spróbuj ponownie."],
    en:["Sending…","Thank you! Your enquiry has been sent.","Could not send your enquiry. Please try again."],
    de:["Wird gesendet…","Vielen Dank! Ihre Anfrage wurde gesendet.","Senden fehlgeschlagen. Bitte versuchen Sie es erneut."],
    fr:["Envoi en cours…","Merci ! Votre demande a été envoyée.","Échec de l’envoi. Veuillez réessayer."]
  }[lang] || ["Sending…","Sent!","Could not send."];

  button.disabled = true;
  notice.textContent = m[0];
  try{
    const r = await fetch(`${API_BASE_URL}/api/contact`, {
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({
        name:f.get("name"),
        email:f.get("email"),
        country:f.get("country"),
        project_type:f.get("type"),
        message:f.get("message"),
        language:lang
      })
    });
    if(!r.ok) throw Error();
    await r.json();
    form.reset();
    notice.textContent = m[1];
  }catch(_){
    notice.textContent = m[2];
  }finally{
    button.disabled = false;
    button.textContent = dict[lang]?.fSubmit || dict.en.fSubmit;
  }
});
